/// Format of the linking QR generated by Vesta (guardian app):
///
///     vesta://link?code=ABCDEF1234
///
/// The bare 10-character code is also accepted, so any reader or a
/// manually generated QR works.
class PairingPayload {
  PairingPayload._();

  static final RegExp _codePattern = RegExp(r'^[A-F0-9]{10}$');

  static bool isValidCode(String code) => _codePattern.hasMatch(code);

  /// Returns the code if [raw] is a valid Vesta QR, or null.
  static String? parse(String? raw) {
    final value = raw?.trim() ?? '';
    if (value.isEmpty) return null;

    final upper = value.toUpperCase();
    if (_codePattern.hasMatch(upper)) return upper;

    final uri = Uri.tryParse(value);
    if (uri == null || uri.scheme.toLowerCase() != 'vesta') return null;
    if (uri.host.toLowerCase() != 'link') return null;

    final code = uri.queryParameters['code']?.trim().toUpperCase() ?? '';
    return _codePattern.hasMatch(code) ? code : null;
  }
}
